/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		route: "customer_actions",
		fields: null,
		params: {
			selectedTab: "Available",
			filterQuery: "-1"
		},
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null,
		navigationOptions: null
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var selectedTab = event.payload.data.elements;
	var filterQuery = event.payload.params.query;
	return {
		route: 'customer_actions',
		fields: null,
		params: {
			'selectedTab': selectedTab[0].toString(),
			'filterQuery' : filterQuery.toString()
		},
		redirect: null,
		passiveNavigation: null,
		title: null,
		multiInstField: null,
		targetRoute: null,
		external: null,
		navigationOptions: null
	};
}
